import sys

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M = int(input[idx]); idx += 1

    adj = [[] for _ in range(N + 1)]
    out_degree = [0] * (N + 1)

    for _ in range(M):
        s = int(input[idx]); idx += 1
        t = int(input[idx]); idx += 1
        adj[s].append(t)
        out_degree[s] += 1

    # Compute original expected values
    E_original = [0.0] * (N + 1)
    for u in range(N, 0, -1):
        if u == N:
            E_original[u] = 0.0
        else:
            sum_edges = 0.0
            for v in adj[u]:
                sum_edges += E_original[v]
            E_original[u] = 1.0 + sum_edges / out_degree[u]

    min_E = E_original[1]

    # Collect all edges
    edges = []
    for s in range(1, N + 1):
        for t in adj[s]:
            edges.append((s, t))

    for u, v in edges:
        if out_degree[u] >= 2:
            # Compute new E when blocking this edge
            E_new = [0.0] * (N + 1)
            # Copy original E values
            for i in range(N + 1):
                E_new[i] = E_original[i]
            # Process nodes in reverse topological order
            for x in range(N, 0, -1):
                if x == u:
                    sum_edges = 0.0
                    for v_prime in adj[x]:
                        if v_prime != v:
                            sum_edges += E_new[v_prime]
                    new_out_degree = out_degree[x] - 1
                    E_new[x] = 1.0 + sum_edges / new_out_degree
                else:
                    sum_edges = 0.0
                    for v_prime in adj[x]:
                        sum_edges += E_new[v_prime]
                    E_new[x] = 1.0 + sum_edges / out_degree[x]
            if E_new[1] < min_E:
                min_E = E_new[1]

    print("{0:.10f}".format(min_E))

