import sys
from collections import defaultdict

def calculate_distance(u_prev, v_curr, t, v_max):
    if u_prev > v_max or v_curr > v_max:
        return float('-inf')
    t1 = max(0, v_max - u_prev)
    t3 = max(0, v_max - v_curr)
    if t1 + t3 <= t:
        t2 = t - t1 - t3
        dist1 = u_prev * t1 + 0.5 * t1**2
        dist2 = v_max * t2
        dist3 = v_max * t3 - 0.5 * t3**2
        return dist1 + dist2 + dist3
    else:
        t_a = (v_curr - u_prev + t) / 2
        t_d = t - t_a
        if t_a < 0 or t_d < 0:
            return float('-inf')
        max_speed = u_prev + t_a
        if max_speed <= v_max:
            dist1 = u_prev * t_a + 0.5 * t_a**2
            dist3 = (u_prev + t_a) * t_d - 0.5 * t_d**2
            return dist1 + dist3
        else:
            t1 = v_max - u_prev
            t_d = t - t1
            if t_d < 0:
                return float('-inf')
            dist1 = u_prev * t1 + 0.5 * t1**2
            dist3 = v_max * t_d - 0.5 * t_d**2
            return dist1 + dist3

